const reserveOutboundCampaignDispatchReceipt = `-- name: ReserveOutboundCampaignDispatchReceipt :one
INSERT INTO public.outbound_campaign_dispatch_receipts(actor_id,handoff_id,key_digest,payload_digest,result_snapshot)
VALUES($1,$2,$3,$4,$5)
ON CONFLICT(actor_id,key_digest) DO UPDATE SET actor_id=public.outbound_campaign_dispatch_receipts.actor_id
RETURNING id,actor_id,handoff_id,key_digest,payload_digest,result_snapshot,created_at
`

type ReserveOutboundCampaignDispatchReceiptParams struct {
	ActorID        int64  `json:"actor_id"`
	HandoffID      int64  `json:"handoff_id"`
	KeyDigest      []byte `json:"key_digest"`
	PayloadDigest  []byte `json:"payload_digest"`
	ResultSnapshot []byte `json:"result_snapshot"`
}

func (q *Queries) ReserveOutboundCampaignDispatchReceipt(ctx context.Context, arg ReserveOutboundCampaignDispatchReceiptParams) (OutboundCampaignDispatchReceipt, error) {
	row := q.db.QueryRow(ctx, reserveOutboundCampaignDispatchReceipt,
		arg.ActorID,
		arg.HandoffID,
		arg.KeyDigest,
		arg.PayloadDigest,
		arg.ResultSnapshot,
	)
	var i OutboundCampaignDispatchReceipt
	err := row.Scan(
		&i.ID,
		&i.ActorID,
		&i.HandoffID,
		&i.KeyDigest,
		&i.PayloadDigest,
		&i.ResultSnapshot,
		&i.CreatedAt,
	)
	return i, err
}

const updateOutboundCampaignDispatchState = `-- name: UpdateOutboundCampaignDispatchState :exec
UPDATE public.outbound_campaign_dispatches SET state=$2, updated_at=now()
WHERE external_effect_id=$1 AND state <> 'blocked'
`

type UpdateOutboundCampaignDispatchStateParams struct {
	ExternalEffectID pgtype.Int8 `json:"external_effect_id"`
	State            string      `json:"state"`
}

func (q *Queries) UpdateOutboundCampaignDispatchState(ctx context.Context, arg UpdateOutboundCampaignDispatchStateParams) error {
	_, err := q.db.Exec(ctx, updateOutboundCampaignDispatchState, arg.ExternalEffectID, arg.State)
	return err
}
